22	            new Edge(1, 3, 8),
23	            new Edge(3, 4, 9),
24	        };
25	
26	        int vertices = 5;
27	        Arrays.sort(edges);
28	        UnionFind uf = new UnionFind(vertices);
29	        int mstWeight = 0;
30	
31	        System.out.println("Kruskal's MST (" + vertices + " vertices, " + edges.length + " edges)");
32	        System.out.println();
33	
34	        for (Edge e : edges) {
35	            if (uf.union(e.u, e.v)) {
36	                System.out.println("  add  " + e);
37	                mstWeight += e.weight;
38	            } else {
39	                System.out.println("  skip " + e + "  <- cycle");
40	            }
